from __future__ import annotations

import json
import os
from typing import Any, Optional
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


DEFAULT_BASE_URL = \"https://api.openai.com/v1\"


class OpenAIResponsesError(RuntimeError):
    \"\"\"Raised when a Responses API request fails.\"\"\"

    def __init__(self, message: str, *, status: Optional[int] = None) -> None:
        super().__init__(message)
        self.status = status


class OpenAIResponsesClient:
    \"\"\"Send private text prompts to OpenAI without logging their contents.\"\"\"

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        *,
        model: Optional[str] = None,
        base_url: Optional[str] = None,
    ) -> None:
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise ValueError(
                \"OPENAI_API_KEY is not set; provide it or pass api_key explicitly.\"
            )

        self.model = model or os.environ.get(\"OPENAI_MODEL\")
        configured_base_url = (
            base_url
            or os.environ.get(\"OPENAI_BASE_URL\")
            or DEFAULT_BASE_URL
        )
        self.base_url = configured_base_url.rstrip(\"/\")

    def send_prompt(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        timeout: float = 60.0,
    ) -> str:
        \"\"\"Send one user text prompt and return the model's text response.\"\"\"
        if not isinstance(prompt, str) or not prompt:
            raise ValueError(\"prompt must be a non-empty string\")

        selected_model = model or self.model
        if not selected_model:
            raise ValueError(
                \"No model selected; set OPENAI_MODEL or pass model explicitly.\"
            )
        if timeout <= 0:
            raise ValueError(\"timeout must be greater than zero\")

        payload = json.dumps(
            {\"model\": selected_model, \"input\": prompt},
            ensure_ascii=False,
        ).encode(\"utf-8\")
        request = Request(
            f\"{self.base_url}/responses\",
            data=payload,
            method=\"POST\",
            headers={
                \"Authorization\": f\"Bearer {self.api_key}\",
                \"Content-Type\": \"application/json\",
                \"User-Agent\": \"openai-stdlib-responses/1.0\",
            },
        )

        try:
            with urlopen(request, timeout=timeout) as response:
                response_data = json.loads(response.read().decode(\"utf-8\"))
        except HTTPError as error:
            raise self._http_error(error) from None
        except URLError as error:
            reason = getattr(error, \"reason\", \"network request failed\")
            raise OpenAIResponsesError(f\"Network error: {reason}\") from None
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise OpenAIResponsesError(\"OpenAI returned an invalid JSON response.\") from None

        text = self._extract_text(response_data)
        if text is None:
            raise OpenAIResponsesError(\"OpenAI response did not contain text output.\")
        return text

    @staticmethod
    def _extract_text(response_data: Any) -> Optional[str]:
        if not isinstance(response_data, dict):
            return None

        output_text = response_data.get(\"output_text\")
        if isinstance(output_text, str):
            return output_text

        parts = []
        output = response_data.get(\"output\", [])
        if not isinstance(output, list):
            return None
        for output_item in output:
            if not isinstance(output_item, dict):
                continue
            content = output_item.get(\"content\", [])
            if not isinstance(content, list):
                continue
            for content_item in content:
                if (
                    isinstance(content_item, dict)
                    and content_item.get(\"type\") == \"output_text\"
                    and isinstance(content_item.get(\"text\"), str)
                ):
                    parts.append(content_item[\"text\"])
        return \"\".join(parts) if parts else None

    @staticmethod
    def _http_error(error: HTTPError) -> OpenAIResponsesError:
        message = f\"OpenAI API error (HTTP {error.code})\"
        try:
            details = json.loads(error.read().decode(\"utf-8\"))
            api_message = details.get(\"error\", {}).get(\"message\")
            if isinstance(api_message, str) and api_message:
                message = f\"{message}: {api_message}\"
        except (AttributeError, UnicodeDecodeError, json.JSONDecodeError, TypeError):
            pass
        return OpenAIResponsesError(message, status=error.code)


def send_prompt(
    prompt: str,
    *,
    model: Optional[str] = None,
    api_key: [REDACTED_SECRET] = None,
    timeout: float = 60.0,
) -> str:
    \"\"\"Convenience function using OPENAI_API_KEY and OPENAI_MODEL.\"\"\"
    client = OpenAIResponsesClient(api_key, model=model)
    return client.send_prompt(prompt, timeout=timeout)
